// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfairDisplay = makeLoadFont('PlayfairDisplay');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfairDisplay();



export type JanuaryCalendarProps = Record<string, any>;

const JanuaryCalendar: React.FC<JanuaryCalendarProps> = ({
  backgroundColor = "#f8f9fa",
  transparentBackground = false,
  durationInSeconds = 8,
  textColor = "#212529",
  highlightColor = "#e03131",
  gridOpacity = 0.4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout metrics optimized for 9:16 (1080x1920)
  const cols = 7;
  const daysInMonth = 31;
  const startDayOffset = 0; // Day 1 is Sunday

  const containerWidth = width * 0.85;
  const cellWidth = containerWidth / cols;
  const cellHeight = cellWidth * 1.3;
  const gridLeft = (width - containerWidth) / 2;
  const gridTop = height * 0.38;

  // Day 27 calculations for transform origin and centering
  const targetDay = 27;
  const targetIndex = targetDay - 1 + startDayOffset;
  const targetCol = targetIndex % cols;
  const targetRow = Math.floor(targetIndex / cols);

  // Absolute center point of Day 27 on the canvas
  const cx27 = gridLeft + targetCol * cellWidth + cellWidth / 2;
  const cy27 = gridTop + targetRow * cellHeight + cellHeight / 2;

  // Animations
  const introSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.6 },
  });

  const zoomStartFrame = fps * 2.5; // Start zoom at 2.5 seconds
  const zoomSpring = spring({
    frame: frame - zoomStartFrame,
    fps,
    config: { damping: 16, mass: 0.9, stiffness: 80 },
  });

  // Zoom Math: We want cx27, cy27 to end up exactly at width/2, height/2
  const maxScale = 4.5;
  const currentScale = interpolate(zoomSpring, [0, 1], [1, maxScale]);

  const endTx = width / 2 - cx27 * maxScale;
  const endTy = height / 2 - cy27 * maxScale;

  const currentTx = interpolate(zoomSpring, [0, 1], [0, endTx]);
  const currentTy = interpolate(zoomSpring, [0, 1], [0, endTy]);

  // Effects for the background (non-27 elements)
  const blurAmount = interpolate(zoomSpring, [0, 1], [0, 3]);
  const grayAmount = interpolate(zoomSpring, [0, 1], [0, 100]);
  const bgLayerOpacity = interpolate(zoomSpring, [0, 1], [1, 0.3]);
  const introYOffset = interpolate(introSpring, [0, 1], [60, 0]);
  const introOpacity = introSpring;

  const headers = ["D", "L", "M", "M", "J", "V", "S"];

  // Helper to render the grid of days to keep JSX clean
  const renderDays = (isHighlightLayer: boolean) => {
    return Array.from({ length: daysInMonth }).map((_, i) => {
      const dayNum = i + 1;
      const isTarget = dayNum === targetDay;

      // Only render the target day in the highlight layer, and everything else in the bg layer
      if (isHighlightLayer && !isTarget) return null;
      if (!isHighlightLayer && isTarget) return null;

      const col = (dayNum - 1 + startDayOffset) % cols;
      const row = Math.floor((dayNum - 1 + startDayOffset) / cols);

      const x = gridLeft + col * cellWidth;
      const y = gridTop + row * cellHeight;

      return (
        <div
          key={dayNum}
          style={{
            position: "absolute",
            left: x,
            top: y,
            width: cellWidth,
            height: cellHeight,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontSize: width * 0.045,
            fontFamily: interFamily,
            fontWeight: isTarget ? 700 : 500,
          }}
        >
          {isTarget && (
            <div
              style={{
                position: "absolute",
                width: cellWidth * 0.85,
                height: cellWidth * 0.85,
                borderRadius: "50%",
                backgroundColor: highlightColor,
                opacity: zoomSpring,
                transform: `scale(${interpolate(zoomSpring, [0, 1], [0.3, 1])})`,
                boxShadow: `0px 10px 20px rgba(224, 49, 49, ${interpolate(
                  zoomSpring,
                  [0, 1],
                  [0, 0.4]
                )})`,
              }}
            />
          )}

          {/* Crossfade text color for target day using overlapping spans */}
          {isTarget ? (
            <>
              <span
                style={{
                  position: "absolute",
                  color: "#ffffff",
                  zIndex: 2,
                  opacity: zoomSpring,
                }}
              >
                {dayNum}
              </span>
              <span
                style={{
                  position: "absolute",
                  color: textColor,
                  zIndex: 1,
                  opacity: 1 - zoomSpring,
                }}
              >
                {dayNum}
              </span>
            </>
          ) : (
            <span style={{ color: textColor }}>{dayNum}</span>
          )}
        </div>
      );
    });
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill
        style={{
          transformOrigin: "0 0",
          transform: `translate(${currentTx}px, ${currentTy}px) scale(${currentScale}) translateY(${introYOffset}px)`,
          opacity: introOpacity,
        }}
      >
        {/* Background Layer: Receives Blur and Grayscale during zoom */}
        <AbsoluteFill
          style={{
            filter: `grayscale(${grayAmount}%) blur(${blurAmount}px)`,
            opacity: bgLayerOpacity,
          }}
        >
          {/* Calendar Title */}
          <div
            style={{
              position: "absolute",
              top: height * 0.18,
              width: "100%",
              textAlign: "center",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: height * 0.01,
            }}
          >
            <span
              style={{
                fontSize: width * 0.11,
                fontFamily: playfairFamily,
                fontWeight: 700,
                color: textColor,
                textTransform: "uppercase",
                letterSpacing: "0.02em",
                lineHeight: 1,
              }}
            >
              Enero
            </span>
            <span
              style={{
                fontSize: width * 0.05,
                fontFamily: interFamily,
                fontWeight: 400,
                color: textColor,
                opacity: 0.6,
                letterSpacing: "0.2em",
              }}
            >
              1984
            </span>
          </div>

          {/* Days of week headers */}
          {headers.map((h, i) => (
            <div
              key={h}
              style={{
                position: "absolute",
                left: gridLeft + i * cellWidth,
                top: gridTop - cellHeight * 0.8,
                width: cellWidth,
                height: cellHeight * 0.5,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                fontSize: width * 0.035,
                fontFamily: interFamily,
                fontWeight: 600,
                color: textColor,
                opacity: 0.4,
              }}
            >
              {h}
            </div>
          ))}

          {/* Subtle Grid Divider */}
          <div
            style={{
              position: "absolute",
              left: gridLeft,
              top: gridTop - cellHeight * 0.2,
              width: containerWidth,
              height: 2,
              backgroundColor: textColor,
              opacity: gridOpacity * 0.2,
            }}
          />

          {/* Render all days EXCEPT Day 27 */}
          {renderDays(false)}
        </AbsoluteFill>

        {/* Foreground Layer: Day 27 stays crisp, full color, and full opacity */}
        <AbsoluteFill>{renderDays(true)}</AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default JanuaryCalendar;